// --- Prompt 模板结构 ---
// 每个占位符对应一个明确的工程职责
const promptTemplate = `
【任务】审查以下 Java 代码的性能问题。

【角色与策略】你是资深 Java 性能工程师。只基于提供的代码和运行指标判断，
不猜测未提供的系统组件或数据量。

【可信上下文】
- 代码片段：\n${codeSnippet}\n
- 运行指标：${metrics}

【输出契约】返回 JSON，格式如下：
{
  "issues": [
    {
      "title": "string",
      "evidence": "string — 引用具体代码行",
      "risk": "low | medium | high",
      "fix": "string — 具体修改建议",
      "priority": number
    }
  ],
  "unknowns": ["string — 不确定需要补充的信息"]
}

【约束】
- 不讨论功能需求或架构重构
- 建议必须兼容 Java 17
- 无法确定的问题写入 unknowns，不要编造

【失败策略】
- 代码片段不足以定位问题时，先在 unknowns 中说明需要补充的指标
- 如果代码无性能问题，issues 为空数组
`;

// --- 输出校验流程 ---
function validateAndRetry(rawOutput, maxRetries = 2) {
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const parsed = JSON.parse(rawOutput);
      // Schema 校验：字段存在性和类型
      if (!Array.isArray(parsed.issues)) throw new Error('issues must be array');
      for (const issue of parsed.issues) {
        if (!issue.title || !issue.evidence || !issue.risk || !issue.fix) {
          throw new Error('missing required field');
        }
        if (!['low', 'medium', 'high'].includes(issue.risk)) {
          throw new Error('invalid risk level');
        }
      }
      // 业务层校验：语义合理性
      // 例如：fix 字段是否包含 Java 17 兼容的 API
      return { status: 'ok', data: parsed };
    } catch (e) {
      if (attempt === maxRetries) {
        return { status: 'failed', reason: e.message, fallback: 'human_review' };
      }
      // 重试时在 prompt 中追加上一次错误信息
      rawOutput = callModel(addErrorContext(promptTemplate, e.message));
    }
  }
}
